'use strict';
let sourceLimit=30;
function sourceInstitutionCard(i){return `<article class="institution-card source-card"><div class="institution-top"><h2><a href="#institution/${esc(i.id)}">${esc(i.name)}</a></h2><span class="source-status">来源收录 · 待核对</span></div><p class="meta">${icon('map-pin')}${esc(i.region)}${i.city?' · '+esc(i.city):''} <span class="muted">${esc(i.id)}</span></p>${i.alias?'<p class="alias muted">别名记录：'+esc(i.alias)+'</p>':''}<p class="card-summary">收录于戒网瘾、特训或封闭矫正相关资料目录。主体、主题相关性与当前状态待核对。</p><div class="source-card-bottom"><span class="muted">${i.sources.length} 个来源入口</span><a href="#institution/${esc(i.id)}">查看档案 ${icon('arrow-right')}</a></div></article>`}
function sourceRecordPackage(i){return {format:'jiewangyin-source-record-v1',version:window.KANJIAN_SOURCE_CATALOG.version,record:i,notice:window.KANJIAN_SOURCE_CATALOG.notice,sources:window.KANJIAN_SOURCE_CATALOG.sources,excluded:'不包含私人原件、联系方式、举报摘要、精确地址和未经授权的媒体。'}}
function sourceRecordHTML(i){return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(i.name)} · 戒网瘾机构观察</title><style>body{font:17px/1.8 system-ui;max-width:760px;margin:24px auto;padding:0 18px;color:#20304a}h1{font-size:25px}a{color:#165ad5}p{overflow-wrap:anywhere}</style><h1>${esc(i.name)}</h1><p>戒网瘾机构观察 · 来源目录 · 待核对</p><p>${esc(i.region)} · ${esc(i.city)} · ${esc(i.id)} · ${esc(i.version)}</p>${i.alias?'<p>原来源别名：'+esc(i.alias)+'</p>':''}<p>${esc(i.summary)}</p><p>${esc(i.regionNote)}</p><h2>来源入口</h2>${i.sources.map((s,n)=>'<p><a href="'+esc(s)+'">来源 '+(n+1)+'：'+esc(s)+'</a></p>').join('')}<p>收录不代表违法认定、机构仍在运营或主体已确认。原目录不同地址和同名记录未自动合并。</p><p>本包仅包含目录字段，不包含原始举报摘要、私人经历或未经授权的媒体。</p></html>`}
function renderSourceInstitution(i){return `<div class="content-column">${backLink()}<header class="detail-header"><p class="eyebrow">戒网瘾 / 特训 / 封闭矫正资料目录</p><h1>${esc(i.name)}</h1><p class="muted">${esc(i.region)}${i.city?' · '+esc(i.city):''} · ${esc(i.id)} · ${esc(i.version)}</p></header><p class="notice">来源收录 · 待核对。收录不代表已经认定违法或确认仍在运营。</p><dl class="source-facts"><dt>别名记录</dt><dd>${esc(i.alias||'来源未提供')}</dd><dt>当前状态</dt><dd>${esc(i.operatingStatus)}</dd><dt>地区说明</dt><dd>${esc(i.regionNote)}</dd><dt>本地核对任务</dt><dd>主体与地址、历史名称、主题相关性、可追溯的具体材料。</dd></dl><section class="reading"><h2>原始来源入口</h2>${i.sources.length?i.sources.map((s,n)=>`<p><a href="${esc(s)}" target="_blank" rel="noopener noreferrer">${icon('external-link')}来源 ${n+1}</a><span class="source-url">${esc(s)}</span></p>`).join(''):'<p>原记录没有可直接打开的完整来源链接，需在本地原件继续核对。</p>'}<p class="muted">私人原件和原始举报摘要保留在本地工作库。当前目录没有为此机构附加演示照片或虚构经历。</p></section><div class="detail-actions"><button class="primary" data-source-share="${i.id}">${icon('share-2')}分享来源档案</button><button data-source-package="${i.id}">${icon('download')}保存可读资料包</button><a class="button" href="#feedback/${i.id}">反馈与更正</a><a class="button" href="#provide/${i.id}">补充机构材料</a></div><a class="button spaced" href="#mutual">进入戒网瘾经历互助</a></div>`}
function renderAccess(){return `<div class="content-column">${backLink('home','机构首页')}<h1>下载与保存</h1><p class="muted">保存公开资料、下载网站副本，或使用离线工具整理图片视频。公开下载无需登录。</p><div class="access-list"><section><h2>${icon('files')}公开目录与可读副本</h2><p>目录含1251份待核对来源记录，附来源许可。机构资料包可直接打开；整站公开包含界面和演示文件，不包含私人数据库及完整互助后台。</p><div class="inline-actions"><a class="button" href="source-catalog.json" download>下载来源目录 JSON</a><a class="button" href="source-catalog.csv" download>下载表格 CSV</a><a class="button" href="site-copy.zip" download>保存公开网站包</a><button id="archive-catalog-export">保存新增公开档案目录</button></div></section><section><h2>${icon('download')}离线整理，再导入</h2><p>先保存草稿说明和私人原件。联网后导入说明，重新选择附件和确认授权。私人原件不要放进公开传播包。</p><div class="inline-actions"><a class="button" href="tools/intake-offline.html" download>下载独立离线投稿页</a><a class="button" href="tools/intake-offline.html">打开离线整理工具</a><label class="button" for="intake-draft-import">导入资料说明 JSON</label><input class="visually-hidden" id="intake-draft-import" type="file" accept="application/json,.json"></div></section><section><h2>${icon('video')}大文件备用办法</h2><p>原件超过上传额度时，先另存原件并用分包工具保存与校验。当前工具按字节分卷和还原，片段不能单独播放；没有承诺已完成视频裁剪或后台自动上传。</p><a class="button" href="tools/media-pack.html">图片视频分包与还原</a></section><section><h2>${icon('history')}备用网址与镜像</h2><p id="mirror-status">正在读取入口清单…</p><div id="mirror-list"></div><p class="muted">仅显示维护者实际登记的入口。多条网址不等于多份已验证备份；目录也可以直接下载保存。</p></section><section><h2>${icon('folder-open')}网页投稿</h2><p>整理机构资料、来源和图片视频；保存服务器草稿后确认提交。互助发帖使用账号，资料线索也可持私人回执查看。</p><div class="inline-actions"><a class="button primary" href="#provide">提供资料</a><a class="button" href="#intake-status">回执与进度</a><a class="button" href="#account">账号与互助</a></div></section></div></div>`}
function renderLiveArchiveShell(){return `<div class="content-column">${backLink()}<div id="archive-record-surface" aria-live="polite"><p>正在读取机构档案…</p></div></div>`}
function renderArchiveBrowse(){const cat=window.KANJIAN_SOURCE_CATALOG;return `<div class="content-column"><h1>戒网瘾机构资料与来源</h1><p class="muted">先查机构记录和原始出处，再补充可以核对的图片、视频与经历。</p><div class="access-list"><section><h2>全国机构来源目录</h2><p>${cat.institutions.length}份来源记录，保留名称、别名、地区、编号与出处。原始举报摘要和私人信息保存在本地工作库。</p><div class="inline-actions"><a class="button primary" href="#home">查找机构</a><a class="button" href="tools/source-directory.html">打开独立来源目录</a><a class="button" href="source-catalog.csv" download>保存表格</a><a class="button" href="source-catalog.json" download>保存JSON目录</a></div></section><section><h2>原资料库与作者</h2>${cat.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a> <span class="muted">${esc(s.license)}</span></p>`).join('')}<a href="SOURCE-LICENSES.txt">来源与处理说明</a></section><section><h2>补充真实材料</h2><p>机构公开页面、新闻或机关文件，以及获准提供的经历与影像，都可以提交核对。现有媒体候选主要为链接，尚未自动采集视频与评论。</p><div class="inline-actions"><a class="button" href="#provide">提供机构资料</a><a class="button" href="#access">手机与备用办法</a></div></section></div><details class="source-details spaced"><summary>查看原有虚构媒体演示</summary><p class="notice">以下内容仅演示图片、视频和资料包操作，没有与真实机构绑定。</p>${renderBrowse()}</details></div>`}
async function archiveHydrate(page,id){
 if(page==='home'){
  const node=$('live-institutions');if(!node)return;try{const data=await intakeAPI('archive/records?'+new URLSearchParams({region:region==='all'?'':region,q:query}));if(!node.isConnected)return;node.innerHTML=data.items.length?'<h2 class="section-head">已整理公开档案</h2>'+data.items.map(r=>`<article class="institution-card"><p class="eyebrow">核对范围见档案说明 · v${r.version}</p><h2><a href="#archive/${r.id}">${esc(r.name)}</a></h2><p>${esc(r.summary)}</p></article>`).join(''):'';}catch{if(node.isConnected)node.innerHTML='';}
 }
 if(page==='access')try{const res=await fetch('access-points.json'),d=await res.json();const mirrors=d.entries.filter(x=>x.enabled&&x.url&&x.kind==='mirror');if($('mirror-status'))$('mirror-status').textContent=mirrors.length?'以下入口由维护者登记；最近测试状态见每条说明。':'尚未登记独立在线镜像；离线目录和网站包已可保存。';if($('mirror-list'))$('mirror-list').innerHTML=mirrors.map(x=>`<p><a href="${esc(x.url)}" rel="noopener noreferrer">${esc(x.label)}</a> · ${esc(x.status||'未进行可访问性验收')}</p>`).join('');}catch{if($('mirror-status'))$('mirror-status').textContent='入口清单暂时不可读取，仍可直接下载资料包。'}
 if(page==='archive')try{const r=await intakeAPI('archive/records/'+id);if($('archive-record-surface'))$('archive-record-surface').innerHTML=`<header class="detail-header"><p class="eyebrow">戒网瘾机构资料 · ${esc(r.region)} ${esc(r.city)}</p><h1>${esc(r.name)}</h1><p class="muted">v${r.version} · ${communityTime(r.updated)}</p></header><p class="notice">${esc(r.verification)}</p><p class="community-copy reading">${esc(r.body)}</p>${r.attachments.map(a=>a.mime.startsWith('image/')?`<img class="archive-media" src="${a.url}" alt="${esc(a.name)}" loading="lazy">`:`<video class="archive-media" controls playsinline src="${a.url}" preload="metadata"></video>`).join('')}<h2>来源</h2>${r.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a></p>`).join('')}<div class="inline-actions"><button class="primary" data-live-share="${r.id}">分享档案</button>${r.allowExport?`<button data-live-package="${r.id}">保存获准公开资料包</button>`:''}<a class="button" href="#feedback/${r.id}">反馈与更正</a></div>`;}catch(e){if($('archive-record-surface'))$('archive-record-surface').innerHTML='<p class="notice">'+esc(e.message)+'</p>'}
}
async function archivePackage(r,sourceRecord=false){
 const enc=new TextEncoder(),files=[],attachments=[];let mediaBytes=0,complete=true;
 if(!sourceRecord)for(const a of r.attachments){if(mediaBytes+a.size>20*1048576){complete=false;continue}const res=await fetch(a.url);if(!res.ok)throw Error('附件没有完整下载，请稍后重试。');const bytes=new Uint8Array(await res.arrayBuffer());if(bytes.length!==a.size)throw Error('附件大小不一致，资料包未完成。');const hash=new KanjianSHA256().update(bytes).hex();if(hash!==a.sha256)throw Error('附件校验失败，资料包未完成。');const name='media/'+a.id+({'image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp','video/mp4':'.mp4','video/webm':'.webm'}[a.mime]||'');files.push({name,bytes});mediaBytes+=a.size;attachments.push({...a,file:name});}
 const html=sourceRecord?sourceRecordHTML(r):`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(r.name)} · 戒网瘾机构观察</title><style>body{font:17px/1.8 system-ui;margin:24px auto;max-width:760px;padding:0 18px;color:#20304a}img,video{max-width:100%}p{white-space:pre-wrap;overflow-wrap:anywhere}</style><h1>${esc(r.name)}</h1><p>戒网瘾机构观察 · v${r.version}</p><p>${esc(r.verification)}</p><p>${esc(r.body)}</p>${attachments.map(a=>a.mime.startsWith('image/')?`<img src="${a.file}" alt="${esc(a.name)}">`:`<video src="${a.file}" controls></video>`).join('')}<h2>来源</h2>${r.sources.map(s=>`<p><a href="${esc(s.url)}">${esc(s.label)}</a></p>`).join('')}${!complete?'<p>媒体未完整打包，请对照public-record.json逐份另存。</p>':''}</html>`;
 const metadata=sourceRecord?sourceRecordPackage(r):{...r,completeMedia:complete,attachments:r.attachments.map(a=>({...a,file:attachments.find(x=>x.id===a.id)?.file||null}))};
 files.push({name:'index.html',bytes:enc.encode(html)},{name:'public-record.json',bytes:enc.encode(JSON.stringify(metadata,null,2))},{name:'先读我.txt',bytes:enc.encode('戒网瘾机构观察\n解压后打开index.html。保留原始来源、授权与版本；资料不代表违法认定。\n'+(complete?'本包包含所选择的目录或获准媒体。':'媒体超过手机单包20MB上限，未打包附件已在目录列明，请分别另存。'))});
 const sums=files.map(f=>new KanjianSHA256().update(f.bytes).hex()+'  '+f.name);files.push({name:'SHA256SUMS.txt',bytes:enc.encode(sums.join('\n')+'\n')});saveBlob('戒网瘾机构观察-'+r.id+'.zip',zipFiles(files));notify(complete?'已生成可读资料包。':'已生成文字包；部分媒体需逐份另存，见包内清单。');
}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{
 if(b.id==='source-more'){sourceLimit+=30;renderResults();}
 if(b.dataset.sourcePackage)await archivePackage(getInstitution(b.dataset.sourcePackage),true);
 if(b.dataset.sourceShare||b.dataset.liveShare){const i=b.dataset.sourceShare?getInstitution(b.dataset.sourceShare):await intakeAPI('archive/records/'+b.dataset.liveShare);const u=new URL(location.href);u.hash=(b.dataset.sourceShare?'institution/':'archive/')+i.id;const text=`戒网瘾机构观察｜${i.name}\n${b.dataset.sourceShare?'来源收录，待核对；收录不代表违法认定。':i.verification}\n资料编号：${i.id} · ${i.version}\n${u.href}`;if(navigator.share)await navigator.share({title:i.name,text,url:u.href});else{try{await navigator.clipboard.writeText(text);notify('已复制档案说明与链接。')}catch{saveBlob(i.id+'-分享说明.txt',new Blob([text]));}}}
 if(b.dataset.livePackage)await archivePackage(await intakeAPI('archive/records/'+b.dataset.livePackage+'/export'));
 if(b.id==='archive-catalog-export'){b.disabled=true;try{const items=[];let after='',pages=0;do{const d=await intakeAPI('archive/records?'+new URLSearchParams({export:'1',after}));items.push(...d.items.map(r=>({...r,attachments:r.attachments.filter(f=>f.exportAllowed)})));after=d.next||'';if(++pages>1000)throw Error('目录过大，请分批导出。');}while(after);saveBlob('戒网瘾机构观察-新增公开目录.json',new Blob([JSON.stringify({format:'kanjian-archive-public-v1',exportedAt:new Date().toISOString(),complete:true,mediaIncluded:false,items},null,2)],{type:'application/json'}));notify('已保存全部获准公开目录；此文件未包含媒体原件。')}finally{b.disabled=false;}}
 }catch(err){if(err.name!=='AbortError')notify(err.message)}});
